"""A single place for environment-dependent backend settings."""

import os
from pathlib import Path


def data_directory() -> Path:
    configured = os.environ.get("APP_DATA_DIR")
    if configured:
        return Path(configured).expanduser().resolve()
    return (Path.home() / ".python-electron-vue-sample").resolve()


def session_token() -> str:
    """Empty in development; randomly generated by Electron in production."""
    return os.environ.get("APP_SESSION_TOKEN", "")


def control_token() -> str:
    return os.environ.get("APP_CONTROL_TOKEN", "")
